"""Captured Emerald native Match Call trace; independent text/witness falsifiers."""
from tests.unit.test_patch_emerald_live import ROOT, problems

CAPTURE = '[gen3] phase field frame=557 map=(0,10)\nCALL_ARMED seq=1 event=1 epoch=7 shows=0 witness=0700000001000200010100009902000000000000000000000000000000000000\nCALL_NATIVE_SHOW count=1 text=0201BF00\nCALL_DELIVERED seq=1 event=1 epoch=7 state=5 window=1 lock=1 witness=07000000010004000201000099020000CE020000000000000000000000000000\nCALL_RECORD seq=1 bytes=01011B011E01CABFBFCCFFFFFFFFBBC6CAC2BBFFFFFFFFFFFFBCBFCEBBFFFFFFFFFFFFFF\nCALL_BUFFER seq=1 bytes=CABFBFCCB4E7FEBBC6CAC2BB00DAD5DDE2E8D9D8ABFBD3E3E9E600CAC9C9BDC2D3BFC8BBFEDDE700DBE3E2D900E8E3E3ABFF\nCALL_BUSY seq=2 request_epoch=8 reason=16 old_witness_record_text_unchanged=1\nCALL_COMPLETE seq=1 event=1 epoch=7 lock=0 task=0 witness=07000000010006000401000099020000CE020000000000000000000000000000\nCALL_COOLDOWN seq=3 reason=18 shows=1\nCALL_ARMED seq=4 event=2 epoch=8 shows=1 witness=0800000004000A0001020000FD2D000000000000000000000000000000000000\nCALL_NATIVE_SHOW count=2 text=0201BF00\nCALL_DELIVERED seq=4 event=2 epoch=8 state=5 window=1 lock=1 witness=0800000004000C0002020000FD2D0000322E0000000000000000000000000000\nCALL_RECORD seq=4 bytes=020000000000FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF\nCALL_BUFFER seq=4 bytes=BFC7BFCCAC00BDD5E200EDE3E9FEDCD9D5E600E1D9AC00ADADADDFE7E7DCADADADFBCEDCD900D7D5E8D7DC00DCD9E6D900DBE3E8FED5EBD5EDAD00CEDCDDE700E4E0D5D7D9FBDDE700D500BEBFBBBE00D4C9C8BFADFEBEE3E2B4E800E0E3E3DF00D6D5D7DFABFF\nCALL_COMPLETE seq=4 event=2 epoch=8 lock=0 task=0 witness=0800000004000E0004020000FD2D0000322E0000000000000000000000000000\nCALL_ARMED seq=5 event=3 epoch=8 shows=2 witness=0800000005001000010300002F5A000000000000000000000000000000000000\nCALL_NATIVE_SHOW count=3 text=0201BF00\nCALL_DELIVERED seq=5 event=3 epoch=8 state=5 window=1 lock=1 witness=0800000005001200020300002F5A0000645A0000000000000000000000000000\nCALL_RECORD seq=5 bytes=03011B011E01CABFBFCCFFFFFFFFBBC6CAC2BBFFFFFFFFFFFFBCBFCEBBFFFFFFFFFFFFFF\nCALL_BUFFER seq=5 bytes=CABFBFCCB4E7FEBBC6CAC2BBFBE0DDE2DFD9D800EBDDE8DC00EDE3E9E6FECAC9C9BDC2D3BFC8BBADFBCEDCD9EDB4E6D900E0DDE2DFD9D8ABFF\nCALL_COMPLETE seq=5 event=3 epoch=8 lock=0 task=0 witness=0800000005001400040300002F5A0000645A0000000000000000000000000000\nCALL_SCOPE SYNTH offline unlock flags; native events1,2,3; busy ownership and cooldown; no flag writes in-run\nRESULT: PASS \n'

def test_native_call_capture_requires_text_delivery_and_release():
    assert not problems("call",CAPTURE,ROOT)
    for old,new in (("0700000001000400","0800000001000400"),
                    ("state=5 window=1 lock=1","state=0 window=1 lock=1"),
                    ("CALL_COMPLETE seq=5","MISSING_COMPLETE seq=5"),
                    ("CALL_BUFFER seq=1 bytes=CABFBFCC","CALL_BUFFER seq=1 bytes=BBBFBFCC"),
                    ("CALL_RECORD seq=1 bytes=01011B01","CALL_RECORD seq=1 bytes=01011C01"),
                    ("old_witness_record_text_unchanged=1","old_witness_record_text_unchanged=0"),
                    ("CALL_COOLDOWN seq=3 reason=18","CALL_COOLDOWN seq=3 reason=0"),
                    ("RESULT: PASS","RESULT: FAIL")):
        assert problems("call",CAPTURE.replace(old,new),ROOT),(old,new)
